/**
 * In-memory location search over a NormalizedNavGraph.
 * Case-insensitive prefix match on label, roomNumber, description, buildingName.
 * Results grouped by building → floor, sorted alphabetically/numerically.
 */

import { useMemo } from 'react';
import type { NormalizedNavGraph } from '../domain/navGraph';
import type { NavNodeType } from '../../src/shared/types';

export interface SearchNode {
  node: import('../../src/shared/types').NavNode;
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
}
export interface SearchFloor { floorId: number; floorNumber: number; nodes: SearchNode[]; }
export interface SearchBuilding { buildingId: number; buildingName: string; floors: SearchFloor[]; }
export interface UseLocationSearchResult { buildings: SearchBuilding[]; totalMatches: number; }

function isPrefixMatch(query: string, target: string): boolean {
  return query.length === 0 || target.toLowerCase().startsWith(query.toLowerCase());
}

export function useLocationSearch(
  graph: NormalizedNavGraph,
  query: string,
  typeFilter?: Set<NavNodeType>,
): UseLocationSearchResult {
  return useMemo(() => {
    const trimmed = query.trim();
    const buildings: SearchBuilding[] = [];
    let totalMatches = 0;

    for (const building of graph.graph.buildings) {
      const matchedFloors: SearchFloor[] = [];

      for (const floor of building.floors) {
        const floorRec = graph.floorById.get(floor.id);
        const floorNumber = floorRec?.floor.floorNumber ?? floor.floorNumber;
        const matchedNodes: SearchNode[] = [];

        for (const node of floor.nodes) {
          if (!node.searchable) continue;
          if (typeFilter && !typeFilter.has(node.type)) continue;
          if (trimmed.length > 0) {
            const labelOk = isPrefixMatch(trimmed, node.label);
            const roomOk = node.roomNumber && isPrefixMatch(trimmed, node.roomNumber);
            const descOk = node.description && isPrefixMatch(trimmed, node.description);
            const bldOk = isPrefixMatch(trimmed, building.name);
            if (!labelOk && !roomOk && !descOk && !bldOk) continue;
          }
          matchedNodes.push({ node, buildingId: building.id, buildingName: building.name, floorId: floor.id, floorNumber });
        }

        if (matchedNodes.length > 0) {
          matchedNodes.sort((a, b) => a.node.label.localeCompare(b.node.label));
          matchedFloors.push({ floorId: floor.id, floorNumber, nodes: matchedNodes });
          totalMatches += matchedNodes.length;
        }
      }

      if (matchedFloors.length > 0) {
        matchedFloors.sort((a, b) => a.floorNumber - b.floorNumber);
        buildings.push({ buildingId: building.id, buildingName: building.name, floors: matchedFloors });
      }
    }

    buildings.sort((a, b) => a.buildingName.localeCompare(b.buildingName));
    return { buildings, totalMatches };
  }, [graph, query, typeFilter]);
}

/**
 * Mobile port of src/client/hooks/useRouteSelection.ts.
 *
 * Changes from web version:
 * - `@shared/types` import replaced with relative `../../src/shared/types`
 * - RouteSelection interface inlined (no shared module dependency)
 */

import type { NavNode } from '../../src/shared/types';
import { useCallback, useMemo, useState } from 'react';

/* ──────────────── Types ──────────────── */

export interface RouteSelection {
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly activeField: 'start' | 'destination';
  readonly bothSelected: boolean;
  readonly setStart: (node: NavNode | null) => void;
  readonly setDestination: (node: NavNode | null) => void;
  readonly setActiveField: (field: 'start' | 'destination') => void;
  /** Assigns a tapped node to the active field, auto-advancing to the other field. */
  readonly setFromTap: (node: NavNode) => void;
  /** Exchanges start and destination. No-op when both are null. */
  readonly swap: () => void;
  readonly clearStart: () => void;
  readonly clearDestination: () => void;
  readonly clearAll: () => void;
}

/* ──────────────── Hook ──────────────── */

/**
 * Manages route selection state — start (A) and destination (B) nodes.
 *
 * `setFromTap` assigns a tapped node to whichever field `activeField` points to,
 * auto-advancing to the other field afterward. If the tapped node is already the
 * OTHER field, it swaps them instead of duplicating.
 */
export function useRouteSelection(): RouteSelection {
  const [start, setStartState] = useState<NavNode | null>(null);
  const [destination, setDestinationState] = useState<NavNode | null>(null);
  const [activeField, setActiveField] = useState<'start' | 'destination'>('start');

  const setStart = useCallback((node: NavNode | null) => {
    setStartState(node);
    setActiveField('destination');
  }, []);

  const setDestination = useCallback((node: NavNode | null) => {
    setDestinationState(node);
    setActiveField('start');
  }, []);

  const setFromTap = useCallback(
    (node: NavNode) => {
      if (activeField === 'start') {
        // If tapped node is already the destination, swap start ↔ destination
        if (destination?.id === node.id) {
          setDestinationState(start);
          setStartState(node);
          setActiveField('destination');
        } else {
          setStartState(node);
          setActiveField('destination');
        }
      } else {
        // activeField === 'destination'
        // If tapped node is already the start, swap start ↔ destination
        if (start?.id === node.id) {
          setStartState(destination);
          setDestinationState(node);
          setActiveField('start');
        } else {
          setDestinationState(node);
          setActiveField('start');
        }
      }
    },
    [activeField, start, destination],
  );

  const swap = useCallback(() => {
    if (start === null && destination === null) return;
    const prevStart = start;
    const prevDest = destination;
    setStartState(prevDest);
    setDestinationState(prevStart);
  }, [start, destination]);

  const clearStart = useCallback(() => {
    setStartState(null);
    setActiveField('start');
  }, []);

  const clearDestination = useCallback(() => {
    setDestinationState(null);
    setActiveField('destination');
  }, []);

  const clearAll = useCallback(() => {
    setStartState(null);
    setDestinationState(null);
    setActiveField('start');
  }, []);

  const bothSelected = useMemo(
    () => start !== null && destination !== null,
    [start, destination],
  );

  return {
    start,
    destination,
    activeField,
    bothSelected,
    setStart,
    setDestination,
    setActiveField,
    setFromTap,
    swap,
    clearStart,
    clearDestination,
    clearAll,
  };
}

/**
 * Route session state machine — pure computation, no React dependencies.
 *
 * Coordinates pathfinding (T01 engine) and direction generation (T01)
 * into a single discriminated union state that drives the UI.
 */

import type { NavNode } from '../../src/shared/types';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
  RouteMode,
} from '../domain/navGraph';
import { MobilePathfindingEngine } from './pathfindingEngine';
import { generateDirections } from './generateDirections';

// ============================================================
// Phase types
// ============================================================

export type RouteSessionPhase =
  | 'idle'
  | 'computing'
  | 'ready'
  | 'no-route'
  | 'error';

// ============================================================
// Discriminated union state types
// ============================================================

export interface RouteSessionIdleState {
  readonly phase: 'idle';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionComputingState {
  readonly phase: 'computing';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionReadyState {
  readonly phase: 'ready';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: PathResult;
  readonly directions: DirectionsResult;
  readonly errorMessage: null;
}

export interface RouteSessionNoRouteState {
  readonly phase: 'no-route';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionErrorState {
  readonly phase: 'error';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: string;
}

/**
 * Discriminated union of all route session states.
 *
 * Discriminant key: `phase`
 *
 * Phase meanings:
 * - `idle`:    No start/destination yet
 * - `computing`: Currently computing (sync, so only an intermediate phase)
 * - `ready`:  Route found — path and directions available
 * - `no-route`: Start & dest selected but no path exists
 * - `error`:  Node not present in graph or other error
 */
export type RouteSessionState =
  | RouteSessionIdleState
  | RouteSessionComputingState
  | RouteSessionReadyState
  | RouteSessionNoRouteState
  | RouteSessionErrorState;

// ============================================================
// Options
// ============================================================

export interface RouteSessionOptions {
  readonly graph: NormalizedNavGraph;
  readonly mode: RouteMode;
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute directions from a found path result.
 * Uses nodeMap and floorMap from the normalized graph.
 */
function computeDirections(
  path: PathResult,
  mode: RouteMode,
  graph: NormalizedNavGraph,
): DirectionsResult {
  // Extract plain NavNode objects from normalized records
  const nodeMap = new Map<string, NavNode>();
  for (const [id, record] of graph.nodeById) {
    nodeMap.set(id, record.node);
  }

  // Extract plain NavFloor objects from normalized records
  const floorMap = new Map<number, import('../../src/shared/types').NavFloor>();
  for (const [id, record] of graph.floorById) {
    floorMap.set(id, record.floor);
  }

  return generateDirections(
    path.nodeIds,
    nodeMap,
    mode,
    floorMap,
  );
}

// ============================================================
// Main computation function
// ============================================================

/**
 * Compute a route session state synchronously.
 *
 * A* is fast enough that no async boundary is needed.
 * The 'computing' phase is included for UI tooling (DevTools)
 * and to make the phase model complete.
 *
 * Transitions:
 * - start === null || destination === null → 'idle'
 * - start/dest valid but not in graph         → 'error'
 * - start/dest in graph, no path found        → 'no-route'
 * - start/dest in graph, path found           → 'ready'
 */
export function computeRouteSession(options: RouteSessionOptions): RouteSessionState {
  const { graph, mode, start, destination } = options;

  // Guard: missing input
  if (start === null || destination === null) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Guard: nodes not in graph
  if (!graph.nodeById.has(start.id) || !graph.nodeById.has(destination.id)) {
    return {
      phase: 'error',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: 'One or both selected nodes are not present in the navigation graph.',
    };
  }

  // Guard: start === destination
  if (start.id === destination.id) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute path
  const engine = new MobilePathfindingEngine(graph);
  const path = engine.findRoute(start.id, destination.id, mode);

  if (!path.found) {
    return {
      phase: 'no-route',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute directions
  const directions = computeDirections(path, mode, graph);

  return {
    phase: 'ready',
    start,
    destination,
    routeMode: mode,
    path,
    directions,
    errorMessage: null,
  };
}

/**
 * useRouteSession — React hook for reactive route session state.
 *
 * Wires together:
 * - start/destination selection (from useRouteSelection)
 * - pathfinding engine (T01 MobilePathfindingEngine)
 * - direction generation (T01 generateDirections)
 *
 * Exposes a discriminated union `sessionState` that the UI
 * can switch on without knowing implementation details.
 */

import { useCallback, useMemo, useState } from 'react';
import type { NavNode } from '../../src/shared/types';
import type { NormalizedNavGraph, RouteMode } from '../domain/navGraph';
import {
  type RouteSessionState,
  type RouteSessionIdleState,
  type RouteSessionReadyState,
  type RouteSessionNoRouteState,
  type RouteSessionErrorState,
  computeRouteSession,
} from './routeSessionState';

// ============================================================
// RouteSelection (from mobile/hooks/useRouteSelection)
// ============================================================

export interface RouteSelection {
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Props
// ============================================================

export interface UseRouteSessionProps {
  readonly graph: NormalizedNavGraph;
  readonly selection: RouteSelection;
}

// ============================================================
// Hook
// ============================================================

/**
 * Reactive route session.
 *
 * `sessionState` is a discriminated union keyed on `phase`:
 *   - 'idle'       → RouteSessionIdleState     (no selection yet)
 *   - 'ready'      → RouteSessionReadyState    (route found, directions ready)
 *   - 'no-route'   → RouteSessionNoRouteState  (selection complete, unreachable)
 *   - 'error'      → RouteSessionErrorState    (invalid node / graph error)
 *
 * `routeMode` tracks 'standard' | 'accessible' independently of selection.
 */
export function useRouteSession({ graph, selection }: UseRouteSessionProps): {
  sessionState: RouteSessionState;
  routeMode: RouteMode;
  setRouteMode: (mode: RouteMode) => void;
} {
  const [routeMode, setRouteModeState] = useState<RouteMode>('standard');

  const setRouteMode = useCallback((mode: RouteMode) => {
    setRouteModeState(mode);
  }, []);

  const sessionState = useMemo<RouteSessionState>(() => {
    return computeRouteSession({
      graph,
      mode: routeMode,
      start: selection.start,
      destination: selection.destination,
    });
    // Re-compute whenever any input changes
  }, [graph, routeMode, selection.start, selection.destination]);

  return { sessionState, routeMode, setRouteMode };
}

// ============================================================
// Type exports for consumers
// ============================================================

export type { RouteSessionState, RouteSessionIdleState, RouteSessionReadyState, RouteSessionNoRouteState, RouteSessionErrorState };

/**
 * DestinationPicker — building/floor/node accordion with fuzzy text search.
 * Pressing a node calls onNodeSelect. "Set Start" / "Set Destination" toggle
 * in header reflects the activeField from RouteSelection.
 */

import { useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { useLocationSearch } from '../../hooks/useLocationSearch';
import type { NormalizedNavGraph } from '../../domain/navGraph';
import type { NavNode } from '../../../src/shared/types';
import type { RouteSelection } from '../../hooks/useRouteSelection';

const DEBOUNCE_MS = 300;

interface Props {
  graph: NormalizedNavGraph;
  selection: RouteSelection;
  onNodeSelect: (node: NavNode) => void;
}

const TYPE_BADGE: Record<string, string> = {
  room: '📍',
  entrance: '🚪',
  elevator: '🛗',
  restroom: '🚻',
  landmark: '⭐',
  stairs: '⬆️',
  ramp: '♿',
  junction: '⬡',
  hallway: '─',
};

const ACCESSIBLE_ICON = '♿';

export function DestinationPicker({ graph, selection, onNodeSelect }: Props) {
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  const { buildings, totalMatches } = useLocationSearch(graph, debouncedQuery);

  const activeLabel = selection.activeField === 'start' ? 'Set Start' : 'Set Destination';
  const otherLabel = selection.activeField === 'start' ? 'Set Destination' : 'Set Start';

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerLabel}>{activeLabel}</Text>
        <Text style={styles.resultCount}>
          {totalMatches} {totalMatches === 1 ? 'result' : 'results'}
        </Text>
      </View>

      {/* Search input */}
      <TextInput
        style={styles.searchInput}
        placeholder="Search location..."
        placeholderTextColor="#64748b"
        value={query}
        onChangeText={setQuery}
        autoCapitalize="none"
        autoCorrect={false}
      />

      {/* Active field indicator */}
      <View style={styles.fieldToggle}>
        <Text style={styles.fieldText}>Picking: </Text>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'start' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('start')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'start' && styles.fieldChipTextActive]}>
            Start {selection.start ? `(${selection.start.label})` : ''}
          </Text>
        </Pressable>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'destination' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('destination')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'destination' && styles.fieldChipTextActive]}>
            Dest {selection.destination ? `(${selection.destination.label})` : ''}
          </Text>
        </Pressable>
        {(selection.start || selection.destination) && (
          <Pressable style={styles.swapButton} onPress={selection.swap}>
            <Text style={styles.swapButtonText}>⇄ Swap</Text>
          </Pressable>
        )}
      </View>

      {/* Results */}
      <FlatList
        data={buildings}
        keyExtractor={item => String(item.buildingId)}
        style={styles.list}
        renderItem={({ item: building }) => (
          <BuildingAccordion
            building={building}
            onNodeSelect={onNodeSelect}
          />
        )}
        ListEmptyComponent={
          <Text style={styles.emptyText}>
            {debouncedQuery ? 'No locations match your search.' : 'No locations available.'}
          </Text>
        }
      />
    </View>
  );
}

/* ─── Sub-components ─── */

interface BuildingAccordionProps {
  building: import('../../hooks/useLocationSearch').SearchBuilding;
  onNodeSelect: (node: NavNode) => void;
}

function BuildingAccordion({ building, onNodeSelect }: BuildingAccordionProps) {
  const [expanded, setExpanded] = useState(false);

  return (
    <View style={styles.buildingSection}>
      <Pressable style={styles.buildingHeader} onPress={() => setExpanded(e => !e)}>
        <View style={styles.buildingInfo}>
          <Text style={styles.buildingName}>{building.buildingName}</Text>
          <Text style={styles.buildingMeta}>
            {building.floors.length} {building.floors.length === 1 ? 'floor' : 'floors'} ·{' '}
            {building.floors.reduce((sum, f) => sum + f.nodes.length, 0)} locations
          </Text>
        </View>
        <Text style={styles.chevron}>{expanded ? '▼' : '▶'}</Text>
      </Pressable>

      {expanded && (
        <View style={styles.floorsContainer}>
          {building.floors.map(floor => (
            <FloorSection key={floor.floorId} floor={floor} onNodeSelect={onNodeSelect} />
          ))}
        </View>
      )}
    </View>
  );
}

interface FloorSectionProps {
  floor: import('../../hooks/useLocationSearch').SearchFloor;
  onNodeSelect: (node: NavNode) => void;
}

function FloorSection({ floor, onNodeSelect }: FloorSectionProps) {
  return (
    <View style={styles.floorSection}>
      <Text style={styles.floorHeader}>Floor {floor.floorNumber}</Text>
      {floor.nodes.map(sn => (
        <NodeRow key={sn.node.id} searchNode={sn} onPress={() => onNodeSelect(sn.node)} />
      ))}
    </View>
  );
}

interface NodeRowProps {
  searchNode: import('../../hooks/useLocationSearch').SearchNode;
  onPress: () => void;
}

function NodeRow({ searchNode, onPress }: NodeRowProps) {
  const { node, buildingName, floorNumber } = searchNode;
  const badge = TYPE_BADGE[node.type] ?? '📍';
  const isAccessible = node.type === 'elevator' || node.type === 'ramp';

  return (
    <Pressable style={styles.nodeRow} onPress={onPress}>
      <Text style={styles.nodeBadge}>{badge}</Text>
      <View style={styles.nodeInfo}>
        <Text style={styles.nodeLabel}>{node.label}</Text>
        <Text style={styles.nodeSubtext}>
          {buildingName} · Floor {floorNumber}
          {node.roomNumber ? ` · Room ${node.roomNumber}` : ''}
        </Text>
      </View>
      {isAccessible && <Text style={styles.accessibleIcon}>{ACCESSIBLE_ICON}</Text>}
    </Pressable>
  );
}

/* ─── Styles (dark theme, campusnav palette) ─── */

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#020617' },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 16, paddingTop: 12, paddingBottom: 8 },
  headerLabel: { color: '#f8fafc', fontSize: 18, fontWeight: '700' },
  resultCount: { color: '#64748b', fontSize: 13 },
  searchInput: {
    marginHorizontal: 16,
    marginBottom: 8,
    backgroundColor: '#0f172a',
    borderColor: '#1e293b',
    borderWidth: 1,
    borderRadius: 10,
    paddingHorizontal: 14,
    paddingVertical: 10,
    color: '#f8fafc',
    fontSize: 15,
  },
  fieldToggle: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingBottom: 10, gap: 8 },
  fieldText: { color: '#94a3b8', fontSize: 13 },
  fieldChip: { backgroundColor: '#0f172a', borderColor: '#334155', borderWidth: 1, borderRadius: 16, paddingHorizontal: 10, paddingVertical: 4 },
  fieldChipActive: { backgroundColor: '#1e3a5f', borderColor: '#38bdf8' },
  fieldChipText: { color: '#94a3b8', fontSize: 12 },
  fieldChipTextActive: { color: '#38bdf8', fontWeight: '600' },
  swapButton: { marginLeft: 'auto', backgroundColor: '#0f172a', borderColor: '#334155', borderWidth: 1, borderRadius: 16, paddingHorizontal: 10, paddingVertical: 4 },
  swapButtonText: { color: '#94a3b8', fontSize: 12 },
  list: { flex: 1 },
  emptyText: { color: '#475569', fontSize: 14, textAlign: 'center', marginTop: 40 },
  buildingSection: { borderBottomColor: '#1e293b', borderBottomWidth: 1 },
  buildingHeader: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 12 },
  buildingInfo: { flex: 1 },
  buildingName: { color: '#f8fafc', fontSize: 16, fontWeight: '600' },
  buildingMeta: { color: '#64748b', fontSize: 12, marginTop: 2 },
  chevron: { color: '#38bdf8', fontSize: 12 },
  floorsContainer: { backgroundColor: '#0a0f1e', paddingLeft: 16 },
  floorSection: { paddingVertical: 6 },
  floorHeader: { color: '#475569', fontSize: 11, fontWeight: '600', letterSpacing: 1, paddingHorizontal: 16, paddingVertical: 4, textTransform: 'uppercase' },
  nodeRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 10, gap: 10 },
  nodeBadge: { fontSize: 16, width: 24, textAlign: 'center' },
  nodeInfo: { flex: 1 },
  nodeLabel: { color: '#e2e8f0', fontSize: 14, fontWeight: '500' },
  nodeSubtext: { color: '#64748b', fontSize: 11, marginTop: 2 },
  accessibleIcon: { fontSize: 14 },
});

/**
 * RoutePreview — step-by-step directions grouped by floor.
 *
 * Props:
 * - directions: DirectionsResult from the route session
 * - floorMap: Map<floorId, NavFloor> from the normalized graph
 * - accessibleMode: boolean to highlight accessible path elements
 * - onFloorChange: callback to switch the active floor
 */

import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { groupDirectionSections } from '../../routing/directionSections';
import type { DirectionsResult, DirectionSection, DirectionStep } from '../../domain/navGraph';
import type { NavFloor } from '../../../src/shared/types';

/* ─── Icons ─── */

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIcon(step: DirectionStep): string {
  return STEP_ICONS[step.icon] ?? '→';
}

/* ─── Step icon color ─── */

function iconColor(step: DirectionStep, accessibleMode: boolean): string {
  if (step.isAccessibleSegment) return '#facc15'; // amber for accessible segments
  if (step.icon === 'arrive') return '#4ade80'; // green for arrival
  if (accessibleMode && (step.icon === 'elevator' || step.icon === 'ramp')) return '#facc15';
  return '#38bdf8'; // cyan for standard
}

/* ─── Duration formatting ─── */

function formatDuration(sec: number): string {
  if (sec < 60) return `${sec}s`;
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return s > 0 ? `${m}m ${s}s` : `${m}m`;
}

/* ─── Distance formatting (normalized → approximate meters) ─── */

function formatDistance(norm: number): string {
  // Normalized coordinate space → approximate real distance
  // Assume campus coordinate space roughly maps to 50m per unit
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

